/** True only for pages that belong in the PRIMARY navigation. */
export function isPrimaryNav(route: string): boolean {
  const l = ROUTE_LAYER[route];
  // Unknown routes default to visible so nothing disappears by accident.
  return l === undefined || l === "L1";
}

/** True for pages surfaced inside The Lab (/portal/lab). */
export function isLabPage(route: string): boolean {
  return ROUTE_LAYER[route] === "L2";
}

/** Routes that should not appear in any menu (archived/cut/merged). */
export function isHidden(route: string): boolean {
  const l = ROUTE_LAYER[route];
  return l === "L3" || l === "CUT" || l === "MERGE";
}
